import{_ as e,H as T,f as a,i as p}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"32 | 全面解析HTTP：从HTTP-0.9到HTTP-3的演变","description":"","frontmatter":{},"headers":[{"level":2,"title":"初识 HTTP","slug":"初识-http","link":"#初识-http","children":[]},{"level":2,"title":"HTTP 详解","slug":"http-详解","link":"#http-详解","children":[{"level":3,"title":"HTTP/0.9","slug":"http-0-9","link":"#http-0-9","children":[]},{"level":3,"title":"HTTP/1.0","slug":"http-1-0","link":"#http-1-0","children":[]},{"level":3,"title":"HTTP/1.1","slug":"http-1-1","link":"#http-1-1","children":[]},{"level":3,"title":"HTTP/2.0","slug":"http-2-0","link":"#http-2-0","children":[]},{"level":3,"title":"HTTP/3.0","slug":"http-3-0","link":"#http-3-0","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Python实战·从0到1搭建直播视频平台/32｜全面解析HTTP：从HTTP-0.9到HTTP-3的演变.md","filePath":"Python实战·从0到1搭建直播视频平台/32｜全面解析HTTP：从HTTP-0.9到HTTP-3的演变.md","lastUpdated":1795533265000}'),i={name:"Python实战·从0到1搭建直播视频平台/32｜全面解析HTTP：从HTTP-0.9到HTTP-3的演变.md"};function l(n,t,P,h,r,s){return T(),a("div",null,[...t[0]||(t[0]=[p('<h1 id="_32-全面解析http-从http-0-9到http-3的演变" tabindex="-1">32 | 全面解析HTTP：从HTTP-0.9到HTTP-3的演变 <a class="header-anchor" href="#_32-全面解析http-从http-0-9到http-3的演变" aria-label="Permalink to &quot;32 | 全面解析HTTP：从HTTP-0.9到HTTP-3的演变&quot;">​</a></h1><p>你好，我是 Barry。</p><p>从这节课开始，我们正式开启直播模块的学习。</p><p>在开发直播平台前，我们需要先学习 HTTP 相关技术。直播平台的核心功能就是基于网络传输实时音视频数据，而 HTTP 是用于在客户端和服务器之间传输数据的协议，它能优化数据传输效率、实现实时性和稳定性，保护用户隐私和数据安全，实现与服务器的交互和集成。</p><p>与此同时，网络知识也是一个技术人员的基本功，但是很多技术人员会忽视掉这一块的内容，在工作和面试中吃了很多的亏，所以这节课我们就以 HTTP 为切入点，系统梳理一下这部分内容。</p><h2 id="初识-http" tabindex="-1">初识 HTTP <a class="header-anchor" href="#初识-http" aria-label="Permalink to &quot;初识 HTTP&quot;">​</a></h2><p>HTTP 是一种用于传输超文本（如 HTML、XML、JSON 等）的应用层协议。它是互联网上最常用的协议之一。</p><p>因为网络协议是我们的必备知识，这里我也顺便说说其他的传输协议。</p><ul><li><p>FTP，用来做文件传输的协议，使用客户端和服务器之间的连接来传输文件。</p></li><li><p>SMTP，用于发送电子邮件的协议，它使用客户端和服务器之间的连接来传输邮件。</p></li><li><p>SSH，这是用于远程登录和管理计算机的协议，它使用客户端和服务器之间的安全连接来传输数据。</p></li></ul><p>HTTP 的发展历程从 20 世纪 80 年代开始算起，当时互联网还处于发展的早期阶段。在 HTTP的早期版本中，它主要用来在客户端和服务器之间传输静态文本和图像文件。</p><p>随着互联网的发展，为了适应不断变化的需求，支持更多功能和特性（例如多媒体、动态内容、安全性、可扩展性等），HTTP 协议也在逐渐扩展和改进。</p><p>从最初的 HTTP/0.9 的版本到现在的 HTTP/3，HTTP 始终在不断地创新优化，所以才成为了互联网最常用的协议之一。</p><p>我这就来为你梳理一下 HTTP 整个发展历程，看看它在每个阶段都有什么发展变革。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/32/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/32/1.png" alt=""></a></p><h2 id="http-详解" tabindex="-1">HTTP 详解 <a class="header-anchor" href="#http-详解" aria-label="Permalink to &quot;HTTP 详解&quot;">​</a></h2><p>梳理完 HTTP 的发展历程和每个阶段做出的重要调整，我们还需要更深入地了解每个阶段的细节，这才是掌握 HTTP 相关知识的核心。掌握了这些，不仅能够巩固我们对 HTTP 的应用理解，也能让你轻松应对在技术面试中网络相关的技能考察。</p><h3 id="http-0-9" tabindex="-1">HTTP/0.9 <a class="header-anchor" href="#http-0-9" aria-label="Permalink to &quot;HTTP/0.9&quot;">​</a></h3><p>我们先从 HTTP/0.9 这个版本开始说起，HTTP/0.9 最初诞生主要用来在网络之间传递 HTML超文本，所以被称为超文本传输协议。</p><p>当时它的实现也非常简单，只有请求行，通过单一的请求行已经能够满足要获取的内容。同时，对于相应内容也只是需要返回数据就可以，这里的数据格式也只能是 HTML 数据格式，这也在后来的发展中成为了它的缺点。</p><p>在后续的使用场景中，用户涌现出大量新的需求，在浏览器传输文件中不单单只有 HTML。例如还有 JS 和 CSS 脚本、图文、音视频等不同类型的文件。所以就需要 HTTP 能够满足更多类型文件的传输，在巨大的需求下 HTTP/1.0 诞生了。</p><h3 id="http-1-0" tabindex="-1">HTTP/1.0 <a class="header-anchor" href="#http-1-0" aria-label="Permalink to &quot;HTTP/1.0&quot;">​</a></h3><p>HTTP/1.0 与 HTTP/0.9 相比做了很大的变革。我们这就一起来看一下，它都做了哪些全面的升级。</p><p>首先，HTTP 1.0 引入了请求头和响应头，主要是为了提供更多的信息来帮助客户端和服务器更好地处理请求和响应，使得 HTTP 协议更加易于使用和维护。</p><p>其次，在请求方法上也开始支持 GET、POST、Head 请求方法。</p><p>最后，通过支持缓存机制，来减轻服务器的负担，也引入了状态码，把请求结果反馈做得更加完善。</p><p>虽然 HTTP/1.0 做了很大的优化和改变，但在后续应用时还是发现一些核心的问题。</p><p>首先，它只有在上一个请求返回之后，才能够再去执行下一个，这样会引起队头阻塞。</p><p>其次，它只能支持一个服务器，只有一个域名。</p><p>最后，在数据传送方面存在一些资源浪费，每次请求都需要提交完整的头部对象进行传递。</p><h3 id="http-1-1" tabindex="-1">HTTP/1.1 <a class="header-anchor" href="#http-1-1" aria-label="Permalink to &quot;HTTP/1.1&quot;">​</a></h3><p>所以，HTTP/1.0 后来逐渐无法满足技术发展需求，这时 HTTP/1.1 应运而生。它在 1.0 的基础上又做了大量更新迭代。</p><p>第一，在效能优化方面，HTTP/1.1 引入了持久连接，大大减少了 TCP 建立连接时消耗的次数，节省了服务器的资源消耗，实现了访问提效。</p><p>第二，通过在请求头中新增 Host 字段，解决服务器只能支持一个域名的问题。通过 Host 字段来表示当前的域名地址，服务器可以通过 Host 值来区分处理不同的域名。</p><p>第三，新增了 e-tags 和 Cache-control，这也是一次重要的变革。这里说个题外话，我们面试当中经常会被问到这两个参数的用途，它们分别用来判断资源是否发生了变化以及如何处理缓存和过期策略。通过使用 e-tags 和 Cache-control，HTTP 1.1 能够更好地支持缓存和优化网络传输，提高了 Web 性能和可靠性。</p><p>第四，添加了 Pipeline。这允许客户端在第一个请求的没完全传输之前，就发送第二个请求，这么做降低了通信的延迟。虽然 Pipeline 在 HTTP/2 才投入稳定的应用，但其实它在 1.1 的阶段就曾投入使用。Pipeline 机制主要还是为了优化性能。具体的执行效果图如下所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/32/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/32/2.png" alt=""></a></p><p>还有其他的一些优化，例如 HTTP/1.1 通过引入 Chunk transfer 机制来实现对动态内容的支持。这个阶段还新增了 5 种新的请求方法，我给你整理在了后面的表格里，你可以看一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/32/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/32/3.png" alt=""></a></p><p>我们看到了在 HTTP/1.1 阶段发生的巨大的更新，在提效节能方面进行了多维度优化。但是宽带利用率和队头阻塞问题还是没有得到充分解决。</p><h3 id="http-2-0" tabindex="-1">HTTP/2.0 <a class="header-anchor" href="#http-2-0" aria-label="Permalink to &quot;HTTP/2.0&quot;">​</a></h3><p>HTTP/2.0 的推出原因不言而喻，目的是为了对 HTTP 进行持续的版本迭代和升级。那么HTTP/2 相比 HTTP/1.1 又做了哪些迭代呢？</p><p>第一，HTTP/2 采用二进制格式而非文本格式，二进制协议解析起来更高效、“线上”更紧凑，更重要的是错误更少。</p><p>第二，为了解决 HTTP/1.x 中存在的队头阻塞问题，HTTP/2 提出了多路复用的概念。多路复用主要解决线头阻塞问题，具体来说就是实现在同一条 connection 之上可以混合发送分属于不同 stream 的 frame，这样就能达到发送多个 request 的功能的效果。</p><p>第三，HTTP/2 使用 Header 压缩机制，持续降低开销。我们都知道，HTTP1 相关版本的header 带有大量信息，而且每次都要重复发送，这样会造成大量的资源消耗。而 HTTP/2 采用 HPACK 算法进行压缩，节省了资源消耗。</p><p>第四，HTTP/2 让服务器可以将响应主动“推送”到客户端缓存中。在 HTTP/2 中，服务器可以在发送响应之前，主动向客户端推送一些资源，这些资源可以是页面中的常见资源，比如图片、样式表、脚本等。通过这种方式，服务器可以在客户端请求资源之前就提前发送响应，减少客户端的等待时间，提高了网页的加载速度。</p><p>同时，HTTP/2 还有增加了一些新特性。</p><ul><li><p>引入了优先级（Priority）机制，允许客户端在请求中指定资源的优先级。</p></li><li><p>引入了流控制（Flow Control）机制，通过在发送方和接收方之间设置缓冲区来控制数据的流量。</p></li><li><p>采用二进制协议，将 HTTP 协议的文本格式改为二进制格式，减少了传输中的开销，提高传输效率。</p></li></ul><p>不过，HTTP/2 依然存在一些缺点，例如在 TCP 传输过程中，由于单个数据包的丢失而造成的阻塞。这是因为在 HTTP/2 中，多个请求是跑在一个 TCP 管道中的，如果其中任意一路数据流中出现了丢包的情况，那么就会阻塞该 TCP 连接中的所有请求，这就是我们常说的 TCP上的队头阻塞。</p><h3 id="http-3-0" tabindex="-1">HTTP/3.0 <a class="header-anchor" href="#http-3-0" aria-label="Permalink to &quot;HTTP/3.0&quot;">​</a></h3><p>综合前面的梳理，可以看出尽管 HTTP/2 在 HTTP/1 的基础上做了很多革新，但是依然有一些缺陷。接下来，我们就看看 HTTP/3 又做了哪些变革。</p><p>HTTP/3.0 的核心目标是提升性能、加快响应速度、保障交互安全性。HTTP/3.0 的核心是QUIC 协议，它是基于 UDP 的协议，这代表着在传输效率上相比之前的版本有了大幅提升，这属于颠覆性的变革，不需要再像之前的版本那样，经历复杂的连接环节。</p><p>HTTP 3.0 还支持更强的安全性，支持使用 TLS 1.3 协议进行加密和保护数据传输，TLS 1.3是最新的安全传输协议。这与之前相比极大的保护了用户的隐私和数据安全，能让用户更加信赖去使用。</p><p>在解决多路复用丢包的线头阻塞问题方面，QUIC 保留了 HTTP2.0 多路复用的特性。在之前的多路复用过程中，同一个 TCP 连接上有多个 stream，只要有一个丢包，那在这个 stream前后的 stream 都会有影响。而在 QUIC 上的 stream 之间并没有依赖关系，所以只关注当下丢包的 stream 就可以，这个方式有效避免了线头阻塞的问题。</p><p>另外，HTTP/3 还实现了有序交付。我们都知道 UDP 是不可靠传输协议，为了实现有序交付，QUIC 在每个数据包都设有一个 offset 字段，也就是偏移量，这样接收端就能根据 offset字段为异步到达的数据包做排序。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>又到了课程的尾声，我们一起来回顾总结一下这节课的重点。</p><p>HTTP 是超文本传输协议，是一种用于在客户端和服务器之间传输数据的协议。除了在线直播平台项目里需要应用到 HTPP 的相关技术知识，我们日常开发里也少不了和 HTTP 打交道。</p><p>针对 HTTP 的发展，我们从最初的 HTTP/0.9 到 HTTP/3 进行了全面解读，了解了在每个阶段HTTP 主要解决的问题，在不同版本都做了哪些突破和优化，又存在哪些不足。你可以结合后面的表格回顾复习一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/32/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/32/4.png" alt=""></a></p><p>最后再分享一点 HTTP 相关知识的学习技巧：你需要明确在不同版本间主要做了哪些创新和解决哪些问题。至于网络部分的考核，更看重你是否能深入掌握 HTTP 的核心原理，希望你在课后参考这个思路再仔细复习一下，这样学习效果会更好。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你觉得 HTTP 和 HTTPS 存在哪些区别？欢迎你总结分享。</p><p>期待你在留言区和我交流互动，也推荐你把这节课分享给身边的更多朋友。</p>',63)])])}const H=e(i,[["render",l]]);export{E as __pageData,H as default};
